{"ASK_BITTEN","role=soldier_nco|tmp=veteran|st=neutral",{"I'd want you to feel safe hearing me out. Not trapped into believing me"}},
{"ASK_BITTEN","role=soldier_green|tmp=fresh|st=neutral|mood=fear",{"God, why? What did you notice? You're scaring me"},false,{[1]="GENERIC"}},
