{"ASK_CAR_FUEL","reg=swat|st=neutral,careful,hostile",{"Negative, our fuel moves the team - back off"}},
{"ASK_CAR_FUEL","reg=military|tmp=fresh|st=friendly,neutral",{"We've got jerry cans on the Humvee, but they're counted - I, I really can't - sorry"}},
{"ASK_CAR_FUEL","reg=military|tmp=seasoned,veteran|st=neutral",{"Fuel point at Fort Knox is off-limits - don't try the cordon for gas, they'll shoot you for a gallon"}},
{"ASK_CAR_FUEL","reg=military|tmp=veteran|st=friendly",{"Deuce-and-a-half is parked on the Ekron road, out of gas - tanks aren't, well, one isn't"}},
{"ASK_CAR_FUEL","reg=elite|st=friendly,neutral",{"Airstrip - crop dusters - Avgas burns, won't love your engine"}},
{"ASK_CAR_FUEL","reg=elite|st=careful,hostile",{"No, move"}},
{"ASK_CAR_FUEL","reg=outlaw,crime|st=neutral",{"Got five gallons of the good stuff hid where you won't find it - talk to me about a price"},false,{[1]="TRADE_OFFER"}},
