{"ASK_CHECKPOINT","reg=gang|tmp=predator|st=hostile|world=road",{"There's a checkpoint on this street - it's me - what are you carrying?"},false,{[1]="GENERIC"}},
{"ASK_CHECKPOINT","role=raider_boss|tmp=predator|st=hostile",{"Them roadblocks are the best thing ever happened to me - nobody can run anywhere"}},
